package com.school.management.entity; import jakarta.persistence.*;import jakarta.validation.constraints.*;
@Entity public class Subject { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank @Column(unique=true) private String code; @NotBlank private String name; private String description; public Subject(){} public Long getId(){return id;} public String getCode(){return code;} public void setCode(String v){code=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} }
